"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Sidebar from "../components/sidebar";
import Navbar from "../../components/Navbar";

export default function EditGroup() {
  const [groupe, setGroupe] = useState(null);
  const [tuteurs, setTuteurs] = useState([]);
  const [sujet, setSujet] = useState("");
  const [idTuteur, setIdTuteur] = useState("");
  const { id } = useParams();
  const router = useRouter();

  useEffect(() => {
    if (id) {
      fetchGroupe();
      fetchTuteurs();
    }
  }, [id]);

  const fetchGroupe = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/getgroupe/${id}`);
      setGroupe(response.data);
      setSujet(response.data.sujet || "");
      setIdTuteur(response.data.idTuteur || "");
    } catch (err) {
      console.error("Erreur récupération groupe:", err);
      alert("Erreur lors du chargement des données");
    }
  };

  const fetchTuteurs = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/tuteurs");
      setTuteurs(response.data);
    } catch (err) {
      console.error("Erreur récupération tuteurs:", err);
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      await axios.put(`http://localhost:5000/api/modifierGroupe/${groupe.idGroupe}`, {
        idTuteur,
        sujet
      });
      router.push('/groupes');
    } catch (err) {
      console.error("Erreur modification:", err);
      alert("Erreur lors de la modification");
    }
  };

  if (!groupe) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-screen bg-gray-100">
      <Sidebar />
      
      <div className="flex flex-col w-full">
        <Navbar />

        <div className="flex flex-1 justify-center items-center p-4">
          <div className="bg-white p-8 rounded-2xl shadow-lg w-full max-w-lg">
            <h1 className="text-2xl font-bold text-gray-800 text-center mb-6">
              Modifier le groupe {groupe.nomGroupe}
            </h1>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Nom du Groupe</label>
                <input
                  type="text"
                  value={groupe.nomGroupe}
                  className="w-full px-3 py-2 border rounded-md bg-gray-100"
                  readOnly
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tuteur</label>
                <select
                  value={idTuteur}
                  onChange={(e) => setIdTuteur(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md"
                >
                  <option value="">Sélectionner un tuteur</option>
                  {tuteurs.map((tuteur) => (
                    <option key={tuteur.idTuteur} value={tuteur.idTuteur}>
                      {tuteur.nom} {tuteur.prenom}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Sujet</label>
                <input
                  type="text"
                  value={sujet}
                  onChange={(e) => setSujet(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md"
                  placeholder="Entrez le sujet du groupe"
                />
              </div>

              <button
                type="submit"
                className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition-colors mt-4"
              >
                Enregistrer les modifications
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}
